import pandas as pd

def clean(df):
    df = df.copy()
    df['species'] = df['species'].str.strip()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', ''), errors='coerce')
    return df

def answer(df):
    df = clean(df)
    return df.groupby('species')['body_mass_g'].mean().to_dict()
